import './App.css';
import { useState } from 'react';
import Header from './components/Header';
import Calendar from './components/Calendar';
import Table from './components/Table';
import Results from './components/Results';

function App() {
  const [range, setRange] = useState([
    {
      startDate: new Date(),
      endDate: new Date(),
      key: 'selection'
    }
  ]);

  const [shifts, setShifts] = useState([
    {
      date: new Date(),
      name: "",
      morningHours: 0,
      eveningHours: 0,
    }
  ]);

  const [tips, setTips] = useState([
    {
      date: new Date(),
      morningTip: 0,
      eveningTip: 0,
    }
  ]);

  function handleRange(item) {
    setRange([item.selection]);
  };

  function handleShifts(date, name, morningOrEvening, hours) {
    setShifts((prevShifts) => {
      // const newShift = {};

      if (morningOrEvening === 'morningHours') {
        const newShift = {
          date: date,
          name: name,
          morningHours: +hours,
          eveningHours: 0,
        }
      } else {
        const newShift = {
          date: date,
          name: name,
          morningHours: 0,
          eveningHours: +hours,
        }
      }

      return [...prevShifts, newShift];
    });
  };

  console.log(shifts)

  return (
    <div className="App">
      <Header />
      <div className='wrapper'>
        <Calendar range={range} onRangeClick={handleRange} />
        <Table range={range} shifts={shifts} onShiftsClick={handleShifts} />
        <Results />
      </div>
    </div>
  );
}

export default App;
